11	// ============================================================================
12	// MoE Dispatch Kernel — PTO-ISA Dual-Path Implementation
13	//
14	// Two independent kernel paths for dispatch communication:
15	//
16	// 1. Direct (2-step): TLOAD remote GM → UB → TSTORE split to local GM
17	//    - Adaptive MOVE_NUM based on UB capacity
18	//    - Cross-rank continuous event-driven ping-pong pipeline
19	//
20	// 2. ViaGM (4-step): TGET remote GM → local temp GM → TLOAD → UB → TSTORE split
21	//    - MegaMoE style with intermediate GM buffer
22	//    - Uses PTO-ISA TGET instruction with built-in ping-pong
23	//
24	// Execution model: AIV-only (vector cores), launched via mpirun for multi-rank
25	// ============================================================================
26	
27	#include <cstdint>
28	#include <cstddef>
29	#include <pto/pto-inst.hpp>
30	#include "pto/common/pto_tile.hpp"
31	
32	// PIPE_FIX is a CCE built-in for cube cores; define as PIPE_V for vec-only compilation
33	// (only used in opPipeList array which we don't access at runtime)
34	#ifndef PIPE_FIX
35	#define PIPE_FIX PIPE_V
36	#endif
37	#include "pto/comm/pto_comm_inst.hpp"
38	
39	#include "moe_dispatch_config.h"
40	
41	#include "comm_context.h"
42	
43	// ============================================================================
44	// Device-side helper: translate local shmem pointer to remote rank's address
45	// ============================================================================
46	template <typename T>
47	AICORE inline __gm__ T* CommRemotePtr(__gm__ CommDeviceContext* ctx, __gm__ T* localPtr, int pe)
48	{
49	    uint64_t localBase = ctx->windowsIn[ctx->rankId];
50	    uint64_t offset = (uint64_t)localPtr - localBase;
51	    return (__gm__ T*)(ctx->windowsIn[pe] + offset);
52	}
53	
54	// ============================================================================
55	// PATH 1: MoeDispatchDirect — 2-step fast path
56	//
57	// TLOAD interleaved rows from remote GM directly into UB, then TSTORE to split
58	// token and scale to separate compact GM destinations.
59	// Cross-rank continuous pipeline with event-driven ping-pong.
60	// ============================================================================
61	template <int HIDDEN_SIZE, int TILE_COLS, int MOVE_NUM>
62	AICORE void MoeDispatchDirect(
63	    __gm__ int8_t* gmA, __gm__ float* gmPerTokenScale, __gm__ int32_t* cumsumMM, __gm__ int32_t* tokenPerExpert,
64	    __gm__ int32_t* preSumBeforeRank, __gm__ uint8_t* shmemBase, __gm__ CommDeviceContext* hcclCtx, int32_t EP,
65	    int32_t expertPerRank, int32_t maxOutputSize, int64_t offsetA, int32_t tpeRowStride = 0, int32_t cumsumStride = 0)
66	{
67	    int32_t myRank = static_cast<int32_t>(hcclCtx->rankId);
68	    int32_t coreIdx = get_block_idx();
69	    int32_t coreNum = get_block_num();
70	    int32_t expNum = (tpeRowStride > 0) ? tpeRowStride : EP * expertPerRank;
71	    int32_t csStride = (cumsumStride > 0) ? cumsumStride : expertPerRank;
72	
73	    constexpr int32_t copyInNum = HIDDEN_SIZE + UB_ALIGN;
74	
75	    using ShapeDyn = pto::Shape<pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC>;
76	    using StrideDyn = pto::Stride<pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC>;
77	    using Global = pto::GlobalTensor<int8_t, ShapeDyn, StrideDyn, pto::Layout::ND>;
78	
79	    using ViewTile = pto::Tile<pto::TileType::Vec, int8_t, MOVE_NUM, TILE_COLS, pto::BLayout::RowMajor, -1, -1>;
80	
81	    constexpr int32_t INTERLEAVED_TILE_BYTES = MOVE_NUM * TILE_COLS;
82	    constexpr int32_t PING_OFFSET = 0;
83	    constexpr int32_t PONG_OFFSET = (INTERLEAVED_TILE_BYTES + 31) & ~31;
84	
85	    ViewTile interleavedPing(MOVE_NUM, TILE_COLS);
86	    ViewTile tokenViewPing(MOVE_NUM, HIDDEN_SIZE);
87	    ViewTile scaleViewPing(MOVE_NUM, UB_ALIGN);
88	    TASSIGN(interleavedPing, PING_OFFSET);
89	    TASSIGN(tokenViewPing, PING_OFFSET);
90	    TASSIGN(scaleViewPing, PING_OFFSET + HIDDEN_SIZE);
91	
92	    ViewTile interleavedPong(MOVE_NUM, TILE_COLS);
93	    ViewTile tokenViewPong(MOVE_NUM, HIDDEN_SIZE);
94	    ViewTile scaleViewPong(MOVE_NUM, UB_ALIGN);
95	    TASSIGN(interleavedPong, PONG_OFFSET);
96	    TASSIGN(tokenViewPong, PONG_OFFSET);
97	    TASSIGN(scaleViewPong, PONG_OFFSET + HIDDEN_SIZE);
98	
99	    uint32_t prevGroupSum = 0;
100	
101	    for (int32_t groupIdx = 0; groupIdx < expertPerRank; ++groupIdx) {
102	        uint32_t currentM = static_cast<uint32_t>(cumsumMM[(EP - 1) * csStride + groupIdx]);
103	
104	        bool hasPending = false;
105	        int32_t pendingPP = 0;
106	        int32_t pendingRows = 0;
107	        __gm__ int8_t* pendTokenDstPtr = nullptr;
108	        __gm__ int8_t* pendScaleDstPtr = nullptr;
109	        int32_t globalChunkIdx = 0;
110	
111	        for (int32_t dstEpIdx = coreIdx; dstEpIdx < EP; dstEpIdx += coreNum) {
112	            uint32_t rowStart;
113	            if (dstEpIdx == 0) {
114	                rowStart = prevGroupSum;
115	            } else {
116	                rowStart = static_cast<uint32_t>(cumsumMM[(dstEpIdx - 1) * csStride + groupIdx]) + prevGroupSum;
117	            }
118	
119	            if (rowStart >= static_cast<uint32_t>(maxOutputSize)) {
120	                continue;
121	            }
122	
123	            int32_t tpeIdx = dstEpIdx * expNum + myRank * expertPerRank + groupIdx;
124	            uint32_t rows = static_cast<uint32_t>(tokenPerExpert[tpeIdx]);
125	
126	            if (rowStart + rows > static_cast<uint32_t>(maxOutputSize)) {
127	                rows = static_cast<uint32_t>(maxOutputSize) - rowStart;
128	            }
129	
130	            if (rows == 0) {
131	                continue;
132	            }
133	
134	            int32_t rowSrc = preSumBeforeRank[dstEpIdx * expertPerRank + groupIdx];
135	
136	            __gm__ uint8_t* otherRankBase = CommRemotePtr(hcclCtx, shmemBase, dstEpIdx);
137	            __gm__ int8_t* remoteSrcPtr =
138	                reinterpret_cast<__gm__ int8_t*>(otherRankBase + offsetA + static_cast<int64_t>(rowSrc) * copyInNum);
139	
140	            int32_t processCount = (static_cast<int32_t>(rows) + MOVE_NUM - 1) / MOVE_NUM;
141	
142	            for (int32_t p = 0; p < processCount; ++p) {
143	                int32_t curRows = MOVE_NUM;
144	                if (p == processCount - 1) {
145	                    int32_t rem = static_cast<int32_t>(rows) - p * MOVE_NUM;
146	                    if (rem < MOVE_NUM)
147	                        curRows = rem;
148	                }
149	
150	                int32_t curPP = globalChunkIdx & 1;
151	                event_t curEvent = curPP ? EVENT_ID1 : EVENT_ID0;
152	                auto& loadTile = curPP ? interleavedPong : interleavedPing;
153	
154	                __gm__ int8_t* chunkSrc = remoteSrcPtr + static_cast<int64_t>(p) * MOVE_NUM * copyInNum;
155	                int64_t srcTotalBytes = static_cast<int64_t>(curRows) * copyInNum;
156	                ShapeDyn srcShape(1, 1, 1, static_cast<size_t>(curRows), static_cast<size_t>(copyInNum));
157	                StrideDyn srcStride(srcTotalBytes, srcTotalBytes, srcTotalBytes, copyInNum, 1);
158	                Global remoteSrcG(chunkSrc, srcShape, srcStride);
159	
160	                loadTile.RowMaskInternal = curRows;
161	                loadTile.ColMaskInternal = TILE_COLS;
162	
163	                if (hasPending) {
164	                    event_t prevEvent = pendingPP ? EVENT_ID1 : EVENT_ID0;
165	                    wait_flag(PIPE_MTE2, PIPE_MTE3, prevEvent);
166	
167	                    auto& prevTokenView = pendingPP ? tokenViewPong : tokenViewPing;
168	                    auto& prevScaleView = pendingPP ? scaleViewPong : scaleViewPing;
169	                    prevTokenView.RowMaskInternal = pendingRows;
170	                    prevTokenView.ColMaskInternal = HIDDEN_SIZE;
171	                    prevScaleView.RowMaskInternal = pendingRows;
172	                    prevScaleView.ColMaskInternal = UB_ALIGN;
173	
174	                    int64_t pendTokenBytes = static_cast<int64_t>(pendingRows) * HIDDEN_SIZE;
175	                    ShapeDyn pendTokenShape(
176	                        1, 1, 1, static_cast<size_t>(pendingRows), static_cast<size_t>(HIDDEN_SIZE));
177	                    StrideDyn pendTokenStride(pendTokenBytes, pendTokenBytes, pendTokenBytes, HIDDEN_SIZE, 1);
178	                    Global pendTokenDstG(pendTokenDstPtr, pendTokenShape, pendTokenStride);
179	
180	                    int64_t pendScaleBytes = static_cast<int64_t>(pendingRows) * UB_ALIGN;
181	                    ShapeDyn pendScaleShape(1, 1, 1, static_cast<size_t>(pendingRows), static_cast<size_t>(UB_ALIGN));
182	                    StrideDyn pendScaleStride(pendScaleBytes, pendScaleBytes, pendScaleBytes, UB_ALIGN, 1);
183	                    Global pendScaleDstG(pendScaleDstPtr, pendScaleShape, pendScaleStride);
184	
185	                    TSTORE(pendTokenDstG, prevTokenView);
186	                    TSTORE(pendScaleDstG, prevScaleView);
187	                    TLOAD(loadTile, remoteSrcG);
188	
189	                    set_flag(PIPE_MTE3, PIPE_MTE2, prevEvent);
190	                    set_flag(PIPE_MTE2, PIPE_MTE3, curEvent);
191	                    wait_flag(PIPE_MTE3, PIPE_MTE2, prevEvent);
192	                } else {
193	                    TLOAD(loadTile, remoteSrcG);
194	                    set_flag(PIPE_MTE2, PIPE_MTE3, curEvent);
195	                }
196	
197	                hasPending = true;
198	                pendingPP = curPP;
199	                pendingRows = curRows;
200	                uint32_t dstRow = rowStart + static_cast<uint32_t>(p * MOVE_NUM);

