240	// ============================================================================
241	// PATH 2: MoeDispatchViaGM — 4-step MegaMoE-style path
242	//
243	// Phase 1: TGET remote GM → tempGmBuffer (using TGET with ping-pong staging)
244	// Phase 2: TLOAD tempGmBuffer → UB → TSTORE split to gmA + gmPerTokenScale
245	// ============================================================================
246	template <int HIDDEN_SIZE, int TILE_COLS, int MOVE_NUM>
247	AICORE void MoeDispatchViaGM(
248	    __gm__ int8_t* gmA, __gm__ float* gmPerTokenScale, __gm__ int8_t* tempGmBuffer, __gm__ int32_t* cumsumMM,
249	    __gm__ int32_t* tokenPerExpert, __gm__ int32_t* preSumBeforeRank, __gm__ uint8_t* shmemBase,
250	    __gm__ CommDeviceContext* hcclCtx, int32_t EP, int32_t expertPerRank, int32_t maxOutputSize, int64_t offsetA)
251	{
252	    int32_t myRank = static_cast<int32_t>(hcclCtx->rankId);
253	    int32_t coreIdx = get_block_idx();
254	    int32_t coreNum = get_block_num();
255	    int32_t expNum = EP * expertPerRank;
256	
257	    constexpr int32_t copyInNum = HIDDEN_SIZE + UB_ALIGN;
258	    constexpr int32_t TGET_TILE_ROWS = 2;
259	
260	    using ShapeDyn = pto::Shape<pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC>;
261	    using StrideDyn = pto::Stride<pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC>;
262	    using Global = pto::GlobalTensor<int8_t, ShapeDyn, StrideDyn, pto::Layout::ND>;
263	
264	    // TGET staging tiles (small, just for remote→local GM transfer)
265	    using TgetTile = pto::Tile<pto::TileType::Vec, int8_t, TGET_TILE_ROWS, TILE_COLS, pto::BLayout::RowMajor, -1, -1>;
266	    TgetTile tgetPing(TGET_TILE_ROWS, TILE_COLS);
267	    TgetTile tgetPong(TGET_TILE_ROWS, TILE_COLS);
