202	AICORE inline void DcciGmRangeNoFence(__gm__ void* ptr, uint64_t bytes)
203	{
204	    if (bytes == 0) {
205	        return;
206	    }
207	    constexpr uint64_t cacheLineBytes = 64;
208	    uint64_t start = reinterpret_cast<uint64_t>(ptr) & ~(cacheLineBytes - 1);
209	    uint64_t end = (reinterpret_cast<uint64_t>(ptr) + bytes + cacheLineBytes - 1) & ~(cacheLineBytes - 1);
210	    for (uint64_t addr = start; addr < end; addr += cacheLineBytes) {
211	        dcci(reinterpret_cast<__gm__ void*>(addr), cache_line_t::SINGLE_CACHE_LINE);
212	    }
213	}
