232	    return ((shape.expertNum + moe_combine::kMoeCombineMetadataPad - 1) / moe_combine::kMoeCombineMetadataPad) *
233	           moe_combine::kMoeCombineMetadataPad;
234	}
235	
236	AICORE inline uint32_t TokenShardBegin(uint32_t totalTokens, uint32_t blockId, uint32_t blockNum)
237	{
238	    if (blockNum == 0) {
239	        return 0;
240	    }
241	    uint32_t base = totalTokens / blockNum;
242	    uint32_t rem = totalTokens % blockNum;
243	    return blockId * base + (blockId < rem ? blockId : rem);
244	}
245	
246	AICORE inline uint32_t TokenShardEnd(uint32_t totalTokens, uint32_t blockId, uint32_t blockNum)
247	{
248	    return TokenShardBegin(totalTokens, blockId + 1, blockNum);
249	}
250	
251	AICORE inline void SoftSyncAiv(__gm__ int32_t* gmWorkspace, uint32_t blockNum)
252	{
253	    GlobalNd<int32_t> syncGlobal = MakeGlobal1D(gmWorkspace, pto::SYNCALL_SOFT_WORKSPACE_INT32);
254	    pto::SYNCALL<pto::SyncAllMode::Soft>(syncGlobal, static_cast<int32_t>(blockNum));
255	}
256	
257	AICORE inline uint32_t EffectiveRowChunk(MoeCombineShape shape)
258	{
259	    (void)shape;
260	    return moe_combine::kMoeCombineRowChunk;
261	}
262	
263	AICORE inline void WaitCombinePhase(
264	    MoeCombineShape shape, LocalPeerWindowView localPeer, uint32_t blockId, uint32_t blockNum, int32_t value)
265	{
266	    if (blockNum == 0) {
267	        return;
268	    }
269	    for (uint32_t peer = blockId; peer < shape.ep; peer += blockNum) {
270	        pto::comm::Signal sig = MakeSignal(localPeer.combineDoneSignal + peer);
271	        pto::comm::TWAIT(sig, value, pto::comm::WaitCmp::GE);
272	    }
273	}
274	
275	struct ReturnSegment {
276	    uint32_t src;
277	    uint32_t localExpert;
278	    uint32_t globalExpert;
279	    int32_t rows;
280	    int32_t srcStart;
281	    int32_t dstStart;
282	    uint32_t chunkCount;
283	};
284	
285	struct ReturnContext {
286	    MoeCombineShape shape;
287	    LocalRouteMetaView routeMeta;
288	    LocalPeerWindowView localPeer;
289	    __gm__ HcclDeviceContext* ctx;
290	    GM_ADDR peerWindow;
291	    __gm__ half* localExpertOutput;
292	    uint32_t myRank;
293	    uint32_t expertNumPadded;
294	    uint32_t rowChunk;
295	    const PeerWindowLayout* peerWindowLayout;
296	};
297	
298	struct ReturnChunk {
299	    uint32_t rowBegin;
300	    uint32_t rowsThisChunk;
301	};
302	
303	struct TileCopyRange {
304	    int32_t srcRow;
305	    int32_t dstRow;
306	    int32_t col;
307	    int32_t cols;
308	};
309	
310	struct RestoreRouteCache {
311	    int32_t rows[kRouteCacheMax];
312	    float probs[kRouteCacheMax];
313	    uint32_t count;
314	    bool enabled;
315	};
316	
317	struct RestoreTileContext {
318	    MoeCombineShape shape;
319	    LocalRouteMetaView routeMeta;
320	    LocalPeerWindowView localPeer;
321	    __gm__ float* probValues;
322	    __gm__ half* output;
323	    uint32_t token;
324	    int32_t col;
325	    int32_t cols;
326	    const RestoreRouteCache* cache;
327	};
328	
329	AICORE inline void AcquireReturnMetadata(
330	    const MoeCombineShape& shape, LocalRouteMetaView routeMeta, uint32_t expertNumPadded)
331	{
332	    AcquireGmRangeBeforeRead(
333	        routeMeta.peerTokenPerExpert, static_cast<uint32_t>(shape.ep * expertNumPadded * sizeof(int32_t)));
334	    AcquireGmRangeBeforeRead(
335	        routeMeta.cumsumPerExpert, static_cast<uint32_t>(shape.ep * expertNumPadded * sizeof(int32_t)));
336	    AcquireGmRangeBeforeRead(routeMeta.dispatchOffset, static_cast<uint32_t>(shape.expertPerRank * sizeof(int32_t)));
337	    AcquireGmRangeBeforeRead(
338	        routeMeta.prevSumBeforeRank, static_cast<uint32_t>(shape.ep * shape.expertPerRank * sizeof(int32_t)));
339	}
340	
341	AICORE inline bool LoadReturnSegment(const ReturnContext& ctx, uint32_t segment, ReturnSegment* out)
342	{
343	    out->src = segment / ctx.shape.expertPerRank;
344	    out->localExpert = segment % ctx.shape.expertPerRank;
345	    out->globalExpert = ctx.myRank * ctx.shape.expertPerRank + out->localExpert;
346	    out->rows =
347	        *(ctx.routeMeta.peerTokenPerExpert + static_cast<uint64_t>(out->src) * ctx.expertNumPadded + out->globalExpert);
348	    if (out->rows <= 0) {
349	        return false;
350	    }
351	    out->srcStart = *(ctx.routeMeta.dispatchOffset + out->localExpert) +
352	                    *(ctx.routeMeta.prevSumBeforeRank + static_cast<uint64_t>(out->src) * ctx.shape.expertPerRank +
353	                      out->localExpert);
354	    out->dstStart = out->globalExpert == 0 ?
355	                        0 :
356	                        *(ctx.routeMeta.cumsumPerExpert + static_cast<uint64_t>(out->src) * ctx.expertNumPadded +
357	                          out->globalExpert - 1);
358	    out->chunkCount = (static_cast<uint32_t>(out->rows) + ctx.rowChunk - 1) / ctx.rowChunk;
359	    return true;
360	}
361	
362	AICORE inline ReturnChunk MakeReturnChunk(const ReturnContext& ctx, const ReturnSegment& segment, uint32_t chunk)
363	{
364	    ReturnChunk out{};
365	    out.rowBegin = chunk * ctx.rowChunk;
366	    out.rowsThisChunk = static_cast<uint32_t>(segment.rows) - out.rowBegin;
367	    out.rowsThisChunk = out.rowsThisChunk < ctx.rowChunk ? out.rowsThisChunk : ctx.rowChunk;
368	    return out;
369	}
370	
371	AICORE inline void CopyLocalTileToPeerWindow(const ReturnContext& ctx, const TileCopyRange& range)
372	{
373	    VecTile<half, kDefaultTileCols> ping(1, range.cols);
374	    VecTile<half, kDefaultTileCols> pong(1, range.cols);
375	    TASSIGN(ping, kPingUbAddr);
376	    TASSIGN(pong, kPongUbAddr);
377	    VecTile<half, kDefaultTileCols>& tile = ((range.col / kDefaultTileCols) & 1) == 0 ? ping : pong;
378	    event_t event = ((range.col / kDefaultTileCols) & 1) == 0 ? EVENT_ID0 : EVENT_ID1;
379	    GlobalNd<half> srcGlobal = MakeGlobal2D(
380	        ctx.localExpertOutput + static_cast<int64_t>(range.srcRow) * static_cast<int32_t>(ctx.shape.k) + range.col, 1,
381	        range.cols, static_cast<int32_t>(ctx.shape.k));
382	    GlobalNd<half> dstGlobal = MakeGlobal2D(
383	        ctx.localPeer.ptrD + static_cast<int64_t>(range.dstRow) * static_cast<int32_t>(ctx.shape.k) + range.col, 1,
384	        range.cols, static_cast<int32_t>(ctx.shape.k));
385	    TLOAD(tile, srcGlobal);
386	    set_flag(PIPE_MTE2, PIPE_MTE3, event);
387	    wait_flag(PIPE_MTE2, PIPE_MTE3, event);
388	    TSTORE(dstGlobal, tile);
389	    WaitStoreTileReusable();
390	}
391	
392	AICORE inline void CopyLocalRowsToPeerWindow(
393	    const ReturnContext& ctx, const ReturnSegment& segment, const ReturnChunk& chunk)
394	{
395	    for (uint32_t row = 0; row < chunk.rowsThisChunk; ++row) {
396	        int32_t dstRow = segment.dstStart + static_cast<int32_t>(chunk.rowBegin + row);
397	        int32_t srcRow = segment.srcStart + static_cast<int32_t>(chunk.rowBegin + row);
398	        for (int32_t col = 0; col < static_cast<int32_t>(ctx.shape.k); col += kDefaultTileCols) {
399	            int32_t cols = static_cast<int32_t>(ctx.shape.k) - col < kDefaultTileCols ?
400	                               static_cast<int32_t>(ctx.shape.k) - col :
401	                               kDefaultTileCols;
402	            CopyLocalTileToPeerWindow(ctx, TileCopyRange{srcRow, dstRow, col, cols});
403	        }
404	    }
405	}
406	
407	AICORE inline void PutRemoteRowsToOwner(
408	    const ReturnContext& ctx, const ReturnSegment& segment, const ReturnChunk& chunk)
409	{
410	    LocalPeerWindowView remotePeer =
411	        MakeRemotePeerWindowView(ctx.ctx, ctx.peerWindow, segment.src, *ctx.peerWindowLayout);
412	    GlobalNd<half> remoteDst = MakeGlobal2D(
413	        remotePeer.ptrD + static_cast<int64_t>(segment.dstStart + static_cast<int32_t>(chunk.rowBegin)) *
414	                              static_cast<int32_t>(ctx.shape.k),
415	        static_cast<int32_t>(chunk.rowsThisChunk), static_cast<int32_t>(ctx.shape.k),
416	        static_cast<int32_t>(ctx.shape.k));
417	    GlobalNd<half> localSrc = MakeGlobal2D(
418	        ctx.localExpertOutput + static_cast<int64_t>(segment.srcStart + static_cast<int32_t>(chunk.rowBegin)) *
419	                                    static_cast<int32_t>(ctx.shape.k),
420	        static_cast<int32_t>(chunk.rowsThisChunk), static_cast<int32_t>(ctx.shape.k),
421	        static_cast<int32_t>(ctx.shape.k));
422	    VecTile<half, kDefaultTileCols> ping(1, kDefaultTileCols);
423	    VecTile<half, kDefaultTileCols> pong(1, kDefaultTileCols);
424	    TASSIGN(ping, kPingUbAddr);
425	    TASSIGN(pong, kPongUbAddr);
426	    pto::comm::TPUT(remoteDst, localSrc, ping, pong);
427	}
428	
429	AICORE inline void ReturnRowsChunk(const ReturnContext& ctx, const ReturnSegment& segment, const ReturnChunk& chunk)
430	{
431	    if (segment.src == ctx.myRank) {
432	        CopyLocalRowsToPeerWindow(ctx, segment, chunk);
433	        return;
434	    }
435	    PutRemoteRowsToOwner(ctx, segment, chunk);
436	}
437	
438	AICORE inline void NotifyCombineOwners(const ReturnContext& ctx, uint32_t blockId, uint32_t blockNum)
439	{
440	    for (uint32_t src = blockId; src < ctx.shape.ep; src += blockNum) {
441	        LocalPeerWindowView remotePeer = MakeRemotePeerWindowView(ctx.ctx, ctx.peerWindow, src, *ctx.peerWindowLayout);
442	        pipe_barrier(PIPE_ALL);
443	        pto::comm::Signal sig = MakeSignal(remotePeer.combineDoneSignal + ctx.myRank);
444	        pto::comm::TNOTIFY(sig, 1, pto::comm::NotifyOp::AtomicAdd);
445	    }
446	}
447	
448	AICORE inline void ReturnExpertRowsToOwners(
449	    MoeCombineShape shape, LocalWorkspaceView workspaceView, LocalRouteMetaView routeMeta,
450	    LocalPeerWindowView localPeer, __gm__ HcclDeviceContext* ctx, GM_ADDR peerWindow, GM_ADDR expertOutput,
451	    uint32_t myRank, uint32_t blockId, uint32_t blockNum, const PeerWindowLayout& peerWindowLayout)
452	{
453	    if (blockNum == 0) {
454	        return;
455	    }
456	    ReturnContext returnCtx{
457	        shape,
458	        routeMeta,
459	        localPeer,
460	        ctx,
461	        peerWindow,
462	        reinterpret_cast<__gm__ half*>(expertOutput),
463	        myRank,
464	        ExpertNumPaddedDevice(shape),
465	        EffectiveRowChunk(shape),
466	        &peerWindowLayout};
467	    uint32_t segmentCount = shape.ep * shape.expertPerRank;
468	    AcquireReturnMetadata(shape, routeMeta, returnCtx.expertNumPadded);
469	
470	    uint32_t chunkBase = 0;
471	    for (uint32_t segment = 0; segment < segmentCount; ++segment) {
472	        ReturnSegment segmentInfo{};
473	        if (!LoadReturnSegment(returnCtx, segment, &segmentInfo)) {
474	            continue;
475	        }
476	        for (uint32_t chunk = 0; chunk < segmentInfo.chunkCount; ++chunk) {
477	            if (((chunkBase + chunk) % blockNum) != blockId) {
478	                continue;
479	            }
480	            ReturnRowsChunk(returnCtx, segmentInfo, MakeReturnChunk(returnCtx, segmentInfo, chunk));
481	        }
482	        chunkBase += segmentInfo.chunkCount;
483	    }
484	    SoftSyncAiv(workspaceView.localSync, blockNum);
485	    NotifyCombineOwners(returnCtx, blockId, blockNum);
486	}
487	
488	AICORE inline void InitRestoreRouteCache(bool enabled, RestoreRouteCache* cache)
489	{
490	    cache->count = 0;
491	    cache->enabled = enabled;
492	}
493	
494	AICORE inline void PrepareRestoreRouteReads(
495	    MoeCombineShape shape, LocalRouteMetaView routeMeta, LocalPeerWindowView localPeer, __gm__ float* probValues,
496	    uint32_t token, RestoreRouteCache* cache)
497	{
498	    for (uint32_t slot = 0; slot < shape.topK; ++slot) {
499	        uint32_t routeIndex = token * shape.topK + slot;
500	        int32_t ptrDRow = *(routeMeta.expandedRowIdx + routeIndex);
501	        if (ptrDRow < 0) {
502	            continue;
503	        }
504	        __gm__ half* ptrRow = localPeer.ptrD + static_cast<int64_t>(ptrDRow) * static_cast<int32_t>(shape.k);
505	        if (!cache->enabled) {
506	            AcquireGmRangeBeforeRead(ptrRow, static_cast<uint64_t>(shape.k) * sizeof(half));
507	            continue;
508	        }
509	        if (cache->count == 0) {
510	            pipe_barrier(PIPE_ALL);
511	        }
512	        cache->rows[cache->count] = ptrDRow;
513	        cache->probs[cache->count] = probValues[routeIndex];
514	        ++cache->count;
515	        DcciGmRangeNoFence(ptrRow, static_cast<uint64_t>(shape.k) * sizeof(half));
516	    }
517	    if (cache->count != 0) {
518	        dsb(DSB_DDR);
519	    }
520	}
521	
522	AICORE inline bool LoadRestoreRoute(const RestoreTileContext& ctx, uint32_t route, int32_t* ptrDRow, float* prob)
523	{
524	    uint32_t routeIndex = ctx.token * ctx.shape.topK + route;
525	    *ptrDRow = ctx.cache->enabled ? ctx.cache->rows[route] : *(ctx.routeMeta.expandedRowIdx + routeIndex);
526	    if (*ptrDRow < 0) {
527	        return false;
528	    }
529	    *prob = ctx.cache->enabled ? ctx.cache->probs[route] : ctx.probValues[routeIndex];
530	    return true;
531	}
532	
533	AICORE inline void AccumulateRestoreTile(
534	    const RestoreTileContext& ctx, VecTile<half, kDefaultTileCols>* outTile, VecTile<half, kDefaultTileCols>* ptrTile)
535	{
536	    uint32_t combineCount = ctx.cache->enabled ? ctx.cache->count : ctx.shape.topK;
537	    pto::Event<pto::Op::TAXPY, pto::Op::TLOAD> axpyToNextLoad;
538	    bool waitForPreviousAxpy = false;
539	    for (uint32_t route = 0; route < combineCount; ++route) {
540	        int32_t ptrDRow = 0;
541	        float prob = 0.0f;
542	        if (!LoadRestoreRoute(ctx, route, &ptrDRow, &prob)) {
543	            continue;
544	        }
545	        __gm__ half* ptrRow = ctx.localPeer.ptrD + static_cast<int64_t>(ptrDRow) * static_cast<int32_t>(ctx.shape.k);
546	        GlobalNd<half> ptrGlobal = MakeGlobal2D(ptrRow + ctx.col, 1, ctx.cols, static_cast<int32_t>(ctx.shape.k));
547	        pto::Event<pto::Op::TLOAD, pto::Op::TAXPY> loadToAxpy;
548	        if (waitForPreviousAxpy) {
549	            axpyToNextLoad.Wait();
550	        }
551	        loadToAxpy = TLOAD(*ptrTile, ptrGlobal);
552	        axpyToNextLoad = TAXPY(*outTile, *ptrTile, static_cast<half>(prob), loadToAxpy);
553	        waitForPreviousAxpy = true;
554	    }
555	    if (waitForPreviousAxpy) {
556	        axpyToNextLoad.Wait();
557	    }
558	}
559	
560	AICORE inline void RestoreColumnTile(const RestoreTileContext& ctx)
561	{
562	    VecTile<half, kDefaultTileCols> outTile(1, ctx.cols);
563	    VecTile<half, kDefaultTileCols> ptrTile(1, ctx.cols);
564	    TASSIGN(outTile, kPingUbAddr);
565	    TASSIGN(ptrTile, kPongUbAddr);
566	    GlobalNd<half> outGlobal = MakeGlobal2D(
567	        ctx.output + static_cast<int64_t>(ctx.token) * static_cast<int32_t>(ctx.shape.k) + ctx.col, 1, ctx.cols,
568	        static_cast<int32_t>(ctx.shape.k));
569	    TEXPANDS(outTile, static_cast<half>(0.0));
570	    pipe_barrier(PIPE_ALL);
571	    AccumulateRestoreTile(ctx, &outTile, &ptrTile);
572	    set_flag(PIPE_V, PIPE_MTE3, EVENT_ID0);
573	    wait_flag(PIPE_V, PIPE_MTE3, EVENT_ID0);
574	    TSTORE(outGlobal, outTile);
575	    WaitStoreTileReusable();
576	}
577	
578	AICORE inline void RestoreOutputRows(
579	    MoeCombineShape shape, LocalRouteMetaView routeMeta, LocalPeerWindowView localPeer, GM_ADDR probs, GM_ADDR outputC,
580	    uint32_t blockId, uint32_t blockNum)
581	{
582	    if (blockNum == 0) {
583	        return;
584	    }
585	    __gm__ float* probValues = reinterpret_cast<__gm__ float*>(probs);
586	    __gm__ half* output = reinterpret_cast<__gm__ half*>(outputC);
587	    uint32_t tokenBegin = TokenShardBegin(shape.m, blockId, blockNum);
588	    uint32_t tokenEnd = TokenShardEnd(shape.m, blockId, blockNum);
589	    for (uint32_t token = tokenBegin; token < tokenEnd; ++token) {
590	        RestoreRouteCache cache{};
591	        InitRestoreRouteCache(shape.topK <= kRouteCacheMax, &cache);
592	        PrepareRestoreRouteReads(shape, routeMeta, localPeer, probValues, token, &cache);
593	        for (int32_t col = 0; col < static_cast<int32_t>(shape.k); col += kDefaultTileCols) {
594	            int32_t cols = static_cast<int32_t>(shape.k) - col < kDefaultTileCols ?
595	                               static_cast<int32_t>(shape.k) - col :
596	                               kDefaultTileCols;
597	            RestoreTileContext tileCtx{shape, routeMeta, localPeer, probValues, output, token, col, cols, &cache};
598	            RestoreColumnTile(tileCtx);
599	        }
600	    }
601	}
602	
603	} // namespace
604	
605	__global__ AICORE void MoeCombineKernel(
606	    MoeCombineShape shape, uint32_t myRank, GM_ADDR expertOutput, GM_ADDR probs, GM_ADDR outputC, GM_ADDR routeMeta,
607	    GM_ADDR peerWindow, GM_ADDR hcclCtx, GM_ADDR workspace)
608	{
609	    WorkspaceLayout workspaceLayout = MakeWorkspaceLayout(shape);
610	    CombineRouteMetaLayout routeMetaLayout = MakeCombineRouteMetaLayout(shape);
611	    PeerWindowLayout peerWindowLayout = MakePeerWindowLayout(shape);
612	    LocalWorkspaceView workspaceView = MakeLocalWorkspaceView(workspace, workspaceLayout);
613	    LocalRouteMetaView localRouteMeta = MakeLocalRouteMetaView(routeMeta, routeMetaLayout);
614	    LocalPeerWindowView localPeer = MakeLocalPeerWindowView(peerWindow, peerWindowLayout);
615	    __gm__ HcclDeviceContext* ctx = reinterpret_cast<__gm__ HcclDeviceContext*>(hcclCtx);
616	    uint32_t blockId = static_cast<uint32_t>(get_block_idx());
617	    uint32_t blockNum = shape.aivBlocks == 0 ? 1 : shape.aivBlocks;
618	    if (shape.ep == 0 || shape.m == 0 || shape.k == 0 || shape.topK == 0 || shape.expertPerRank == 0 ||
619	        shape.expertNum == 0 || blockId >= blockNum) {
620	        return;
621	    }
622	
623	    ReturnExpertRowsToOwners(
624	        shape, workspaceView, localRouteMeta, localPeer, ctx, peerWindow, expertOutput, myRank, blockId, blockNum,
625	        peerWindowLayout);
626	    WaitCombinePhase(shape, localPeer, blockId, blockNum, static_cast<int32_t>(moe_combine::kMoeCombineSignalValue));
627	    SoftSyncAiv(workspaceView.localSync, blockNum);
628	    RestoreOutputRows(shape, localRouteMeta, localPeer, probs, outputC, blockId, blockNum);
629	    SoftSyncAiv(workspaceView.localSync, blockNum);
630	}
631	
632	namespace moe_combine {
633	
634	void LaunchMoeCombineKernel(
635	    MoeCombineShape shape, uint32_t myRank, uint8_t* expertOutput, uint8_t* probs, uint8_t* outputC, uint8_t* routeMeta,
636	    uint8_t* peerWindow, uint8_t* hcclCtx, uint8_t* workspace, void* stream, uint32_t launchBlockCount)
637	{
638	    MoeCombineKernel<<<launchBlockCount, nullptr, stream>>>(
639	        shape, myRank, expertOutput, probs, outputC, routeMeta, peerWindow, hcclCtx, workspace);
640	}
641	
642	} // namespace moe_combine
