{
    const uint16_t stageNum = tilingData_->frontReorderTiling.stageNum;

    FrontReorderProcess<CType_, ExpertPerRank>(xGM_, expertIdGM_, expertTokenNumsGM_, workspaceGM_, tilingData_);
    ProcessFixedGroups(stageNum);
}

