143	
144	    AICORE inline uint32_t LocalGroupGlobalExpert(uint32_t groupIdx) const { return rank_ * expertPerRank_ + groupIdx; }
145	
146	    AICORE inline uint32_t TokenCountByGlobalExpert(uint32_t srcRank, uint32_t globalExpert) const
147	    {
148	        return static_cast<uint32_t>(
149	            tokenPerExpertPtr_[static_cast<uint64_t>(srcRank) * expertNumAligned_ + globalExpert]);
150	    }
151	
152	    AICORE inline uint32_t RawRowsForLocalGroup(uint32_t srcRank, uint32_t groupIdx) const
153	    {
154	        return TokenCountByGlobalExpert(srcRank, LocalGroupGlobalExpert(groupIdx));
155	    }
156	
157	    AICORE inline uint32_t CopyCumsumBeforeSource(uint32_t srcRank, uint32_t groupIdx) const
158	    {
159	        if (srcRank == 0U) {
160	            return 0U;
161	        }
162	        return static_cast<uint32_t>(cumsumMMPtr_[static_cast<uint64_t>(srcRank - 1U) * expertPerRank_ + groupIdx]);
163	    }
164	
165	    AICORE inline void FetchRankGroupRows(
166	        uint32_t srcRank, uint32_t groupIdx, uint32_t prevGroupSum, int32_t& pingpongIdx) const
167	    {
168	        const uint32_t rawRows = RawRowsForLocalGroup(srcRank, groupIdx);
169	        const uint32_t dstRowBase = prevGroupSum + CopyCumsumBeforeSource(srcRank, groupIdx);
170	        uint32_t rows = 0U;
171	        if (dstRowBase < maxOutputSize_) {
172	            rows = rawRows;
173	            if (dstRowBase + rows > maxOutputSize_) {
174	                rows = maxOutputSize_ - dstRowBase;
175	            }
176	        }
177	        if (rows == 0U) {
178	            return;
179	        }
180	        const uint32_t srcRowBase =
181	            static_cast<uint32_t>(preSumBeforeRankPtr_[static_cast<uint64_t>(srcRank) * expertPerRank_ + groupIdx]);
182	        __gm__ int8_t* remotePackedRows = reinterpret_cast<__gm__ int8_t*>(
183	            remoteWindow_.RemoteBase(peerMemoryLayout_.offsetA, static_cast<int32_t>(srcRank)));
184	        __gm__ int8_t* remoteSrc = remotePackedRows + static_cast<uint64_t>(srcRowBase) * PackedRowStride();
185	        FetchRemoteDispatchedRows(
186	            gmAPtr_ + static_cast<uint64_t>(dstRowBase) * problemK_, perTokenScalePtr_ + dstRowBase, remoteSrc, rows,
187	            pingpongIdx);
188	    }
189	
190	    AICORE inline void StorePerTokenRows(
191	        __gm__ int8_t* dst, uint64_t ubOffsetBytes, uint32_t ubRowStride, uint32_t outputOffset, uint32_t rowNum) const
192	    {
193	        if (PayloadWordTStoreSupported(ubRowStride)) {
194	            using ShapeDyn = pto::Shape<pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC>;
195	            using StrideDyn = pto::Stride<pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC>;
196	            using PayloadWordGlobal = pto::GlobalTensor<uint32_t, ShapeDyn, StrideDyn, pto::Layout::ND>;
197	            using PayloadWordTile = pto::Tile<
198	                pto::TileType::Vec, uint32_t, kDispatchGatherUbMoveNum, kDispatchGatherPackedWordTileCols,
199	                pto::BLayout::RowMajor, -1, -1>;
200	
201	            const uint32_t wordCols = problemK_ / sizeof(uint32_t);
202	            ShapeDyn payloadShape(1, 1, 1, rowNum, wordCols);
203	            StrideDyn payloadStride(rowNum * wordCols, rowNum * wordCols, rowNum * wordCols, wordCols, 1);
204	            PayloadWordGlobal payloadDst(
205	                reinterpret_cast<__gm__ uint32_t*>(dst + outputOffset), payloadShape, payloadStride);
206	            PayloadWordTile payloadTile(rowNum, wordCols);
207	            pto::TASSIGN(payloadTile, ubOffsetBytes);
208	            pto::TSTORE(payloadDst, payloadTile);
209	            return;
210	        }
211	
212	        using ShapeDyn = pto::Shape<pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC>;
213	        using StrideDyn = pto::Stride<pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC>;
214	        using PayloadGlobal = pto::GlobalTensor<int8_t, ShapeDyn, StrideDyn, pto::Layout::ND>;
215	        using PayloadTile = pto::Tile<
216	            pto::TileType::Vec, int8_t, kDispatchGatherUbMoveNum, kDispatchGatherPackedTileCols, pto::BLayout::RowMajor,
217	            -1, -1>;
218	
219	        for (uint32_t colOffset = 0U; colOffset < problemK_; colOffset += kDispatchGatherPayloadStoreCols) {
220	            const uint32_t curCols = problemK_ - colOffset > kDispatchGatherPayloadStoreCols ?
221	                                         kDispatchGatherPayloadStoreCols :
222	                                         problemK_ - colOffset;
223	            ShapeDyn payloadShape(1, 1, 1, rowNum, curCols);
224	            StrideDyn payloadStride(rowNum * problemK_, rowNum * problemK_, rowNum * problemK_, problemK_, 1);
225	            PayloadGlobal payloadDst(dst + outputOffset + colOffset, payloadShape, payloadStride);
226	            PayloadTile payloadTile(rowNum, curCols);
227	            pto::TASSIGN(payloadTile, ubOffsetBytes + colOffset);
228	            pto::TSTORE(payloadDst, payloadTile);
229	        }
230	    }
231	
232	    AICORE inline void StorePerTokenScales(
233	        __gm__ float* dstScale, uint64_t ubOffsetBytes, uint32_t ubRowStride, uint32_t outputOffset,
234	        uint32_t rowNum) const
235	    {
236	        using ShapeDyn = pto::Shape<pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC>;
237	        using StrideDyn = pto::Stride<pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC>;
238	        using ScaleGlobal = pto::GlobalTensor<float, ShapeDyn, StrideDyn, pto::Layout::ND>;
239	        using ScaleTile = pto::Tile<
240	            pto::TileType::Vec, float, kDispatchGatherUbMoveNum, kDispatchGatherPackedScaleTileCols,
241	            pto::BLayout::RowMajor, -1, -1>;
242	
243	        ShapeDyn scaleShape(1, 1, 1, rowNum, 1);
244	        StrideDyn scaleStride(rowNum, rowNum, rowNum, 1, 1);
245	        ScaleGlobal scaleDst(dstScale + outputOffset, scaleShape, scaleStride);
246	        ScaleTile scaleTile(rowNum, 1);
247	        pto::TASSIGN(scaleTile, ubOffsetBytes + problemK_);
248	        pto::TSTORE(scaleDst, scaleTile);
249	    }
250	
251	    AICORE inline void StorePendingDispatchGatherChunk(
252	        __gm__ int8_t* dst, __gm__ float* dstScale, const DispatchGatherChunk& chunk) const
253	    {
254	        const event_t event = DispatchGatherBufferEvent(chunk.bufferId);
255	        const uint64_t ubOffsetBytes = DispatchGatherPackedUbOffset(chunk.bufferId);
256	        wait_flag(PIPE_MTE2, PIPE_MTE3, event);
257	        StorePerTokenRows(dst, ubOffsetBytes, chunk.ubRowStride, chunk.rowOffset * problemK_, chunk.rowNum);
258	        StorePerTokenScales(dstScale, ubOffsetBytes, chunk.ubRowStride, chunk.rowOffset, chunk.rowNum);
259	        set_flag(PIPE_MTE3, PIPE_MTE2, event);
260	    }
261	
262	    AICORE inline void FetchRemoteDispatchedRows(
263	        __gm__ int8_t* dst, __gm__ float* dstScale, __gm__ int8_t* src, uint32_t rows, int32_t& pingpongId) const
264	    {
265	        using ShapeDyn = pto::Shape<pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC>;
266	        using StrideDyn = pto::Stride<pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC, pto::DYNAMIC>;
267	        using PackedGlobal = pto::GlobalTensor<int8_t, ShapeDyn, StrideDyn, pto::Layout::ND>;
268	        using PackedTile = pto::Tile<
269	            pto::TileType::Vec, int8_t, kDispatchGatherUbMoveNum, kDispatchGatherPackedTileCols, pto::BLayout::RowMajor,
270	            -1, -1>;
271	
272	        const uint32_t packedStride = PackedRowStride();
273	        const uint32_t processCount = static_cast<uint32_t>(ceilDiv(rows, kDispatchGatherUbMoveNum));
274	        for (uint32_t processIndex = 0U; processIndex < processCount; ++processIndex) {
275	            pingpongId = (pingpongId + 1) % static_cast<int32_t>(kDispatchBufferNum);
276	            const uint32_t bufferId = static_cast<uint32_t>(pingpongId);
277	            const event_t event = DispatchGatherBufferEvent(bufferId);
278	            const uint64_t ubOffsetBytes = DispatchGatherPackedUbOffset(bufferId);
279	            const uint32_t rowOffset = processIndex * kDispatchGatherUbMoveNum;
280	            const uint32_t rowNum =
281	                rows - rowOffset > kDispatchGatherUbMoveNum ? kDispatchGatherUbMoveNum : rows - rowOffset;
282	
283	            wait_flag(PIPE_MTE3, PIPE_MTE2, event);
284	            ShapeDyn packedShape(1, 1, 1, rowNum, packedStride);
285	            StrideDyn packedStrideShape(
286	                rowNum * packedStride, rowNum * packedStride, rowNum * packedStride, packedStride, 1);
287	            __gm__ int8_t* remoteBatchSrc = src + static_cast<uint64_t>(rowOffset) * packedStride;
288	            PackedGlobal remotePackedG(remoteBatchSrc, packedShape, packedStrideShape);
289	            PackedTile packedTile(rowNum, packedStride);
290	            pto::TASSIGN(packedTile, ubOffsetBytes);
291	            pto::TLOAD(packedTile, remotePackedG); // 从远端GM加载数据到UB
292	            set_flag(PIPE_MTE2, PIPE_MTE3, event);
293	
294	            DispatchGatherChunk chunk;
295	            chunk.bufferId = bufferId;
296	            chunk.rowOffset = rowOffset;
297	            chunk.rowNum = rowNum;
298	            chunk.ubRowStride = kDispatchGatherPackedTileCols;
299	            StorePendingDispatchGatherChunk(dst, dstScale, chunk);
300	        }
301	    }
302	
303	    AICORE inline void ProcessRankSplitCopy() const
304	    {
305	        if ASCEND_IS_AIV {
306	            const bool activeCopyCore = rankSize_ != 0U && coreIdx_ < rankSize_;
307	            uint32_t prevGroupSum = 0U;
308	            int32_t pingpongIdx = 0;
309	            for (uint32_t groupIdx = 0U; groupIdx < expertPerRank_; ++groupIdx) {
310	                const uint32_t currentM = static_cast<uint32_t>(
311	                    cumsumMMPtr_[static_cast<uint64_t>(rankSize_ - 1U) * expertPerRank_ + groupIdx]);
312	                if (activeCopyCore) {
313	                    PrepareDispatchGatherCopyEvents();
314	                    for (uint32_t srcRank = coreIdx_; srcRank < rankSize_; srcRank += coreNum_) {
